input.content:
(function(){
  var W=164,H=74;
  var slot={sales:[352,24],orders:[180,152],refunds:[524,152],email:[8,280],total:[180,280],currency:[352,280],daily:[524,280]};
  var full={sales:'sales',orders:'sales.orders',refunds:'sales.refunds',email:'sales.orders.email',total:'sales.orders.total',currency:'sales.orders.currency',daily:'reports.daily'};
  var paths={
    'sales>orders':'M434,98 L262,152','sales>refunds':'M434,98 L606,152',
    'orders>email':'M262,226 L90,280','orders>total':'M262,226 L262,280','orders>currency':'M262,226 L434,280',
    'daily>orders':'M548,280 L344,189','daily>total':'M606,354 V382 H262 V354'
  };
  function n(s,id,owner,desc,own,inh,o){o=o||{};o.s=s;o.id=id;o.owner=owner;o.desc=desc;o.own=own;o.inh=inh;return o}
  function e(a,b,k,st){return {a:a,b:b,k:k,st:st||'live'}}
  function tbl(caption,head,rows,note){
    var h='<div class="rows"><table><caption>'+caption+'</caption><tr>'+head.map(function(c){return '<th>'+c+'</th>'}).join('')+'</tr>';
    rows.forEach(function(r){
      var start=r[0]!=='';
      h+='<tr>'+r.map(function(c,i){
        var cls=[];
        if(start) cls.push('grp-start');
        if(i===r.length-1 && r.length>5) cls.push('wrap');
        return '<td'+(cls.length?' class="'+cls.join(' ')+'"':'')+'>'+c+'</td>';
      }).join('')+'</tr>';
    });
    h+='</table></div>';
    if(note) h+='<p class="fnote">'+note+'</p>';
    return h;
  }
  var stages=[
   {title:'Start: six nodes',
    text:['Each box lists the name and id, then the owner, the description and the tags.',
          '<code>sales.orders</code> has the owner asha, a description, and the tag <code>pii</code>. <code>sales.orders.email</code> has the owner dana and the tag <code>contact</code>.',
          'Tags flow down the solid arrows, so <code>sales.orders.email</code> also inherits <code>pii</code> and <code>finance</code>. Owner and description do not flow anywhere. They belong to one node only.',
          '<code>reports.daily</code> references the table and one column. References carry no tags.'],
    table:'',
    nodes:[n('sales','n1',null,'Sales schema',['finance'],[]),
           n('orders','n2','asha','One row per order',['pii'],['finance']),
           n('refunds','n5',null,'One row per refund',[],['finance']),
           n('email','n3','dana','Customer email',['contact'],['pii','finance']),
           n('total','n4','asha','Order total, EUR',[],['pii','finance']),
           n('daily','n6',null,'Daily revenue',[],[])],
    edges:[e('sales','orders','c'),e('sales','refunds','c'),e('orders','email','c'),e('orders','total','c'),e('daily','orders','r'),e('daily','total','r')]},

   {title:'A person deletes the sales.orders subtree (operation d1)',
    text:['The table, its two columns, and all five arrows touching them leave the live graph.',
          'Nothing is thrown away. Three node rows and five arrow rows move into the journal, labelled <code>d1</code>. Each node row keeps its owner, description and own tags.',
          'Inherited tags are not saved. They will be worked out again when the node comes back.'],
    table:tbl('What the journal holds for d1',['id','qualified_name','owner','description','tags'],[
      ['n2','sales.orders','asha','One row per order','["pii"]'],
      ['n3','sales.orders.email','dana','Customer email','["contact"]'],
      ['n4','sales.orders.total','asha','Order total, EUR','[]']]),
    nodes:[n('sales','n1',null,'Sales schema',['finance'],[]),
           n('refunds','n5',null,'One row per refund',[],['finance']),
           n('daily','n6',null,'Daily revenue',[],[]),
           n('orders','n2','asha','One row per order',['pii'],['finance'],{state:'ghost',note:'in journal'}),
           n('email','n3','dana','Customer email',['contact'],['pii','finance'],{state:'ghost',note:'in journal'}),
           n('total','n4','asha','Order total, EUR',[],['pii','finance'],{state:'ghost',note:'in journal'})],
    edges:[e('sales','refunds','c'),e('sales','orders','c','ghost'),e('orders','email','c','ghost'),e('orders','total','c','ghost'),e('daily','orders','r','ghost'),e('daily','total','r','ghost')]},

   {title:'Work continues before anyone asks for undo',
    text:['A person adds the tag <code>gdpr</code> to <code>sales</code> and rewrites the description of <code>sales.refunds</code>. Neither node was part of the delete.',
          'An ingest run finds no live <code>sales.orders</code>, so it creates one with a new id, <code>n7</code>. The same happens for <code>sales.orders.email</code> (<code>n8</code>). It also adds a column that never existed, <code>sales.orders.currency</code> (<code>n9</code>). Ingest leaves owner, description and tags empty.',
          'On the new <code>sales.orders</code> (n7) a person sets the owner to ben.',
          'On the new <code>sales.orders.email</code> (n8) a person writes a new description, sets the tags to <code>hashed</code>, and records that the column has no owner.',
          'Two nodes now claim each of those names, and their fields disagree. The table lists every field.'],
    table:tbl('Two nodes claim each name',['name','field','old node, in the journal','new node, live','who wrote the live value'],[
      ['sales.orders<br>n2 vs n7','description','One row per order','empty','nobody'],
      ['','owner','asha','ben','a person, after the delete'],
      ['','tags','["pii"]','empty','nobody'],
      ['sales.orders.email<br>n3 vs n8','description','Customer email','Hashed customer email','a person, after the delete'],
      ['','owner','dana','none','a person, who emptied it on purpose'],
      ['','tags','["contact"]','["hashed"]','a person, after the delete']]),
    nodes:[n('sales','n1',null,'Sales schema',['finance','gdpr'],[],{fresh:['gdpr']}),
           n('refunds','n5',null,'Approved refunds only',[],['finance','gdpr'],{fresh:['gdpr'],chg:{desc:1}}),
           n('daily','n6',null,'Daily revenue',[],[]),
           n('orders','n7','ben',null,[],['finance','gdpr'],{newId:1,shadow:1,note:'old n2 in journal',chg:{owner:1}}),
           n('email','n8',null,'Hashed customer email',['hashed'],['finance','gdpr'],{newId:1,shadow:1,note:'old n3 in journal',ownerSet:1,chg:{owner:1,desc:1},fresh:['hashed']}),
           n('currency','n9',null,null,[],['finance','gdpr'],{newId:1}),
           n('total','n4','asha','Order total, EUR',[],['pii','finance'],{state:'ghost',note:'in journal'})],
    edges:[e('sales','orders','c'),e('sales','refunds','c'),e('orders','email','c'),e('orders','currency','c'),e('orders','total','c','ghost'),e('daily','orders','r','ghost'),e('daily','total','r','ghost')]},

   {title:'undo d1',
    text:['<code>sales.orders</code>: the name is held by <code>n7</code>, so old <code>n2</code> is <b class="m">merged</b> into it. The owner stays ben. The description and the tag <code>pii</code> were never written on n7, so they are filled in from <code>n2</code>.',
          '<code>sales.orders.email</code>: old <code>n3</code> is <b class="m">merged</b> into <code>n8</code>. A person wrote all three fields on n8 after the delete, so all three stay: the new description, no owner, the tag <code>hashed</code>. Nothing from n3 is applied, and the report lists what was left out.',
          '<code>sales.orders.total</code>: the name is free and its parent now lives on as <code>n7</code>, so it is <b class="r">restored</b> with its old id <code>n4</code>, its owner and its description.',
          'Arrows: two <code>contains</code> arrows already exist and are counted as <b class="m">merged</b>. The arrow to <code>total</code> and the reference to the table are re-aimed at <code>n7</code>, also <b class="m">merged</b>. The reference to <code>total</code> is <b class="r">restored</b> unchanged.',
          'Inherited tags are recomputed. <code>pii</code> flows from <code>n7</code> to <code>email</code>, <code>total</code> and <code>currency</code>. <code>total</code> picks up <code>gdpr</code>, which was added while it was gone.',
          'The rewritten description of <code>sales.refunds</code> is untouched.'],
    table:tbl('Field by field, after undo',['name','field','in the journal','live before undo','after undo','what happened'],[
      ['sales.orders<br>n2 into n7','description','One row per order','empty','One row per order','<b class="f">filled</b>: nobody had written it'],
      ['','owner','asha','ben','ben','<b>kept</b>: a person wrote it; asha is listed as not restored'],
      ['','tags','["pii"]','empty','["pii"]','<b class="f">filled</b>: nobody had written it'],
      ['','inherited tags','not saved','finance, gdpr','finance, gdpr','recomputed from <code>sales</code>'],
      ['sales.orders.email<br>n3 into n8','description','Customer email','Hashed customer email','Hashed customer email','<b>kept</b>: a person wrote it'],
      ['','owner','dana','none','none','<b>kept</b>: a person emptied it on purpose'],
      ['','tags','["contact"]','["hashed"]','["hashed"]','<b>kept</b>: a person wrote it; the two lists are not mixed'],
      ['','inherited tags','not saved','finance, gdpr','pii, finance, gdpr','recomputed: <code>pii</code> arrives from n7'],
      ['sales.orders.total<br>n4','description','Order total, EUR','not live','Order total, EUR','<b class="r">restored</b> as it was'],
      ['','owner','asha','not live','asha','<b class="r">restored</b> as it was'],
      ['','tags','[]','not live','[]','<b class="r">restored</b> as it was'],
      ['','inherited tags','not saved','not live','pii, finance, gdpr','recomputed: <code>gdpr</code> is new for this node']],
      'Owner, description and own tags follow the same rule. Inherited tags are the only value that is always recomputed.'),
    nodes:[n('sales','n1',null,'Sales schema',['finance','gdpr'],[]),
           n('refunds','n5',null,'Approved refunds only',[],['finance','gdpr']),
           n('daily','n6',null,'Daily revenue',[],[]),
           n('orders','n7','ben','One row per order',['pii'],['finance','gdpr'],{newId:1,state:'merged',note:'merged ← n2',fresh:['pii'],chg:{desc:1}}),
           n('email','n8',null,'Hashed customer email',['hashed'],['pii','finance','gdpr'],{newId:1,state:'merged',note:'merged ← n3',ownerSet:1,fresh:['pii']}),
           n('total','n4','asha','Order total, EUR',[],['pii','finance','gdpr'],{state:'restored',note:'restored',fresh:['gdpr']}),
           n('currency','n9',null,null,[],['pii','finance','gdpr'],{newId:1,fresh:['pii']})],
    edges:[e('sales','refunds','c'),e('orders','currency','c'),e('sales','orders','c','mer'),e('orders','email','c','mer'),e('orders','total','c','mer'),e('daily','orders','r','mer'),e('daily','total','r','res')]}
  ];
  function tagSpans(d){
    if(!d.own.length && !d.inh.length) return '<tspan class="tg-none">no tags</tspan>';
    var out=[],fresh=d.fresh||[];
    d.own.forEach(function(t){out.push([t,'tg-own'+(fresh.indexOf(t)>=0?' tg-new':'')])});
    d.inh.forEach(function(t){out.push([t,'tg-inh'+(fresh.indexOf(t)>=0?' tg-new':'')])});
    return out.map(function(p,i){return '<tspan class="'+p[1]+'"'+(i?' dx="5"':'')+'>'+p[0]+'</tspan>'}).join('');
  }
  function drawNode(d){
    var x=slot[d.s][0],y=slot[d.s][1],st=d.state||'live',chg=d.chg||{},o='';
    if(d.shadow) o+='<rect class="ghostbox" x="'+(x-6)+'" y="'+(y-6)+'" width="'+W+'" height="'+H+'" rx="6"/>';
    o+='<g class="node '+st+'"><rect class="nb" x="'+x+'" y="'+y+'" width="'+W+'" height="'+H+'" rx="6"/>';
    o+='<text class="nm" x="'+(x+9)+'" y="'+(y+18)+'">'+full[d.s]+'</text>';
    o+='<text class="id'+(d.newId?' idnew':'')+'" x="'+(x+W-9)+'" y="'+(y+18)+'" text-anchor="end">'+d.id+'</text>';
    var ov=d.owner?'<tspan dx="4">'+d.owner+'</tspan>':'<tspan class="none" dx="4">'+(d.ownerSet?'none, on purpose':'none')+'</tspan>';
    o+='<text class="fl'+(chg.owner?' chg':'')+'" x="'+(x+9)+'" y="'+(y+33)+'"><tspan class="lb">owner</tspan>'+ov+'</text>';
    o+='<text class="fl'+(chg.desc?' chg':'')+'" x="'+(x+9)+'" y="'+(y+47)+'">'+(d.desc?d.desc:'<tspan class="none">no description</tspan>')+'</text>';
    o+='<text class="tg" x="'+(x+9)+'" y="'+(y+63)+'">'+tagSpans(d)+'</text></g>';
    if(d.note) o+='<text class="note '+st+'" x="'+(x+2)+'" y="'+(y-(d.shadow?11:7))+'">'+d.note+'</text>';
    return o;
  }
  function drawEdge(d){
    var mk=d.st==='res'?'ah-res':d.st==='mer'?'ah-mer':'ah';
    return '<path class="edge '+d.k+' '+d.st+'" d="'+paths[d.a+'>'+d.b]+'" marker-end="url(#'+mk+')"/>';
  }
  var svg=document.getElementById('story'),txt=document.getElementById('storytext'),ft=document.getElementById('fieldtable');
  var tabs=[].slice.call(document.querySelectorAll('.tabs button'));
  function show(i){
    var s=stages[i];
    svg.innerHTML=s.edges.map(drawEdge).join('')+s.nodes.map(drawNode).join('');
    svg.setAttribute('aria-label','The example graph at stage '+(i+1)+': '+s.title);
    txt.innerHTML='<h4>'+s.title+'</h4><ul>'+s.text.map(function(t){return '<li>'+t+'</li>'}).join('')+'</ul>';
    ft.innerHTML=s.table||'';
    tabs.forEach(function(b,j){b.setAttribute('aria-selected',j===i?'true':'false')});
  }
  tabs.forEach(function(b){b.addEventListener('click',function(){show(+b.dataset.i)})});
  show(0);
})();

