input.content:
// Runs the story script against a stub DOM and clicks through every story and step.
const fs = require('fs');
const src = fs.readFileSync(process.argv[2], 'utf8');
const els = {};
function el(id) {
  if (!els[id]) els[id] = { id, innerHTML: '', textContent: '', attrs: {}, handlers: {},
    setAttribute(k, v) { this.attrs[k] = v; },
    addEventListener(t, f) { this.handlers[t] = f; } };
  return els[id];
}
global.document = { getElementById: el };
new Function(src)();
const click = (id, i) => els[id].handlers.click({ target: { closest: () => ({ dataset: { i: String(i) } }) } });
const count = (id) => (els[id].innerHTML.match(/<button/g) || []).length;
const nFlows = count('flowtabs');
let steps = 0, problems = [];
for (let f = 0; f < nFlows; f++) {
  click('flowtabs', f);
  const nSteps = count('stagetabs');
  for (let s = 0; s < nSteps; s++) {
    click('stagetabs', s);
    steps++;
    const svg = els.story.innerHTML, where = `story ${f + 1} step ${s + 1}`;
    if (/undefined|NaN/.test(svg)) problems.push(where + ': undefined/NaN in drawing');
    if (/undefined/.test(els.storytext.innerHTML + els.fieldtable.innerHTML)) problems.push(where + ': undefined in text');
    if (!/<rect/.test(svg) ) problems.push(where + ': no nodes drawn');
    // every node id shown at most once among live (non-ghost, non-skipped) boxes
    const live = [...svg.matchAll(/<g class="node (live|restored|merged)">.*?<text class="nm"[^>]*>([^<]+)</g)].map(m => m[2]);
    if (new Set(live).size !== live.length) problems.push(where + ': a name is live twice: ' + live);
  }
  console.log(`story ${f + 1}: ${nSteps} steps`);
}
console.log(`${nFlows} stories, ${steps} steps rendered`);
if (problems.length) { console.log('PROBLEMS:\n' + problems.join('\n')); process.exit(1); }
console.log('no problems found');

